static void require(bool ok,const juce::String& message){if(!ok)throw std::runtime_error(message.toStdString());}
static void pump(int ms){auto end=juce::Time::getMillisecondCounterHiRes()+ms;do{juce::MessageManager::getInstance()->runDispatchLoopUntil(2);[[NSRunLoop currentRunLoop]runMode:NSDefaultRunLoopMode beforeDate:[NSDate dateWithTimeIntervalSinceNow:.002]];}while(juce::Time::getMillisecondCounterHiRes()<end);}
static NSView* nativeView(juce::Component& c){require(c.getPeer()!=nullptr,"Missing native peer");return (__bridge NSView*)c.getPeer()->getNativeHandle();}
static void capture(juce::Component& component,const juce::File& file){NSView*view=nativeView(component);[view displayIfNeeded];NSBitmapImageRep*image=[view bitmapImageRepForCachingDisplayInRect:[view bounds]];[view cacheDisplayInRect:[view bounds]toBitmapImageRep:image];NSData*png=[image representationUsingType:NSBitmapImageFileTypePNG properties:@{}];require([png writeToFile:[NSString stringWithUTF8String:file.getFullPathName().toRawUTF8()]atomically:YES],"Native capture");}
static juce::AudioProcessorParameter* param(juce::AudioProcessor& p,int i){return p.getParameters()[i];}
static void ready(juce::AudioProcessor& p){for(int n=0;n<2000;n++){juce::AudioBuffer<float> block(2,128);block.clear();juce::MidiBuffer midi;p.processBlock(block,midi);pump(5);auto s=param(p,26)->getText(param(p,26)->getValue(),1024);if(s=="READY"&&n>=7)return;require(s=="LOADING"||s=="READY","Status parameter "+param(p,26)->getName(100)+" text=["+s+"] value="+juce::String(param(p,26)->getValue()));pump(5);}throw std::runtime_error("Loading timeout");}
class Head:public juce::AudioPlayHead{public:double ppq=0,rate=44100;bool playing=false;juce::Optional<PositionInfo> getPosition()const override{PositionInfo p;p.setBpm(120);p.setPpqPosition(ppq);p.setIsPlaying(playing);p.setTimeInSamples(int64_t(ppq*rate/2));return p;}};
static double audio(juce::AudioProcessor& p,Head& head,int note=60,bool notes=true,int blocks=160){double sum=0;int frames=0;juce::MidiBuffer midi;for(int n=0;n<blocks;n++){int count=std::array<int,5>{32,64,128,256,512}[n%5];juce::AudioBuffer<float>b(2,count);b.clear();midi.clear();if(notes&&n==0)midi.addEvent(juce::MidiMessage::noteOn(1,note,uint8_t(110)),0);if(notes&&n==110)midi.addEvent(juce::MidiMessage::noteOff(1,note),count-1);p.processBlock(b,midi);for(int c=0;c<2;c++)for(int f=0;f<count;f++){auto x=b.getSample(c,f);require(std::isfinite(x),"Nonfinite audio");sum+=x*x;}frames+=count;head.ppq+=count*2/head.rate;}return std::sqrt(sum/(frames*2));}
static void mouse(juce::Component&root,float x,float y,NSEventType type){NSView*view=nativeView(root);std::cout<<" ROOT "<<[[view className]UTF8String]<<" subviews="<<[[view subviews]count]<<std::endl;for(NSView*child in [view subviews]){std::cout<<" CHILD "<<[[child className]UTF8String]<<" hidden="<<[child isHidden]<<" frame="<<[[NSStringFromRect([child frame])description]UTF8String]<<" subviews="<<[[child subviews]count]<<std::endl;}NSPoint local=NSMakePoint(x,[view isFlipped]?y:NSHeight([view bounds])-y);std::cout<<"MOUSE root="<<root.getWidth()<<","<<root.getHeight()<<" native="<<NSWidth([view bounds])<<","<<NSHeight([view bounds])<<" flip="<<[view isFlipped]<<" local="<<local.x<<","<<local.y<<std::endl;NSPoint where=[view convertPoint:local toView:nil];NSPoint screen=[[view window]convertPointToScreen:where];std::cout<<" SCREEN "<<screen.x<<","<<screen.y<<" top="<<[NSWindow windowNumberAtPoint:screen belowWindowWithWindowNumber:0]<<" expected="<<[[view window]windowNumber]<<" frame="<<[NSStringFromRect([[view window]frame])UTF8String]<<std::endl;NSView*target=[view hitTest:[view convertPoint:local toView:[view superview]]];require(target!=nil,"Native view hit test");std::cout<<" target="<<[[target className]UTF8String]<<" window="<<[[view window]windowNumber]<<" event="<<where.x<<","<<where.y<<" targetLocal="<<[target convertPoint:where fromView:nil].x<<","<<[target convertPoint:where fromView:nil].y<<" targetBounds="<<[NSStringFromRect([target bounds])UTF8String]<<" targetWindow="<<[[target window]windowNumber]<<std::endl;NSEvent*event=[NSEvent mouseEventWithType:type location:where modifierFlags:0 timestamp:[NSProcessInfo processInfo].systemUptime windowNumber:[[view window]windowNumber] context:nil eventNumber:0 clickCount:1 pressure:1];SEL dispatch=NSSelectorFromString(type==NSEventTypeLeftMouseDown?@"asyncMouseDown:":@"asyncMouseUp:");if([target respondsToSelector:dispatch])[target performSelector:dispatch withObject:event];else if(type==NSEventTypeLeftMouseDown)[target mouseDown:event];else[target mouseUp:event];pump(25);}
static void click(juce::Component&root,const juce::String&name){const juce::StringArray names{"PLAY","EDIT","KIT"};int i=names.indexOf(name);require(i>=0,"Unknown tab");float x=22+(NSWidth([nativeView(root) bounds])-44)/3.f*(i+.5f);mouse(root,x,198,NSEventTypeLeftMouseDown);mouse(root,x,198,NSEventTypeLeftMouseUp);pump(120);}

#include "transport_stop.inc"
static void testFormat(const juce::String& fmt,const juce::File& bundle,const juce::File& out){
 // Register this exact build for this process so the system AU cache cannot
 // redirect the probe to an earlier bundle with the same product identifier.
 void* auLibrary=nullptr;if(fmt=="AudioUnit"){auLibrary=dlopen(bundle.getChildFile("Contents/MacOS/Rhythmer Engines").getFullPathName().toRawUTF8(),RTLD_NOW|RTLD_LOCAL);if(!auLibrary)throw std::runtime_error(dlerror());auto factory=(AudioComponentFactoryFunction)dlsym(auLibrary,"Rhythmer_EnginesAUFactory");require(factory!=nullptr,"AU factory");AudioComponentDescription d{};d.componentType='aumu';d.componentSubType='Rhen';d.componentManufacturer='JzRh';require(AudioComponentRegister(&d,CFSTR("Jazzy Rhythmer: Rhythmer Engines QA"),0x7fff0100,factory)!=nullptr,"AU local registration");}
 juce::AudioPluginFormatManager manager;juce::addDefaultFormatsToManager(manager);juce::OwnedArray<juce::PluginDescription> types;
 for(auto*f:manager.getFormats())if(f->getName()==fmt)f->findAllTypesForFile(types,bundle.getFullPathName());
 require(types.size()==1,"Expected one "+fmt+" instrument, got "+juce::String(types.size()));juce::String error;
 auto plugin=manager.createPluginInstance(*types[0],44100,512,error);require(plugin!=nullptr,error);std::cout<<fmt<<" parameters "<<plugin->getParameters().size()<<std::endl;for(int n=0;n<std::min(6,plugin->getParameters().size());n++)std::cout<<n<<" "<<plugin->getParameters()[n]->getName(100)<<std::endl;require(plugin->getParameters().size()>=89,"Parameter count");for(int i:{1,2,26})std::cout<<"VALUE "<<i<<" ["<<param(*plugin,i)->getText(param(*plugin,i)->getValue(),1024)<<"]"<<std::endl;for(int i=0;i<89;i++)require(!param(*plugin,i)->getName(100).contains("GEN"),"Generator parameter exposed");Head head;plugin->setPlayHead(&head);plugin->prepareToPlay(44100,512);ready(*plugin);
 if(!std::getenv("RHYTHMER_QA_UI_ONLY")&&!std::getenv("RHYTHMER_QA_SKIP_STOP"))stopCheck(*plugin,head,fmt);
 if(std::getenv("RHYTHMER_QA_STOP_ONLY")){plugin->releaseResources();return;}
 for(double rate:{44100.,48000.,96000.}){if(std::getenv("RHYTHMER_QA_UI_ONLY"))break;head.rate=rate;plugin->releaseResources();plugin->prepareToPlay(rate,512);param(*plugin,1)->setValueNotifyingHost(3/21.f);ready(*plugin);double rms=audio(*plugin,head);require(rms>1e-7,"Silent sound");std::cout<<fmt<<" AUDIO "<<rate<<" rms="<<rms<<std::endl;}
 head.rate=44100;plugin->releaseResources();plugin->prepareToPlay(44100,512);
 auto editor=std::unique_ptr<juce::AudioProcessorEditor>(plugin->createEditorAndMakeActive());require(editor!=nullptr,"Missing custom editor");if(!std::getenv("RHYTHMER_QA_AUDIO_ONLY")){editor->addToDesktop(juce::ComponentPeer::windowHasTitleBar);editor->setVisible(true);editor->setAlwaysOnTop(true);editor->toFront(true);[nativeView(*editor).window setFrameOrigin:NSMakePoint(20,20)];[nativeView(*editor).window makeKeyAndOrderFront:nil];pump(250);}if(std::getenv("RHYTHMER_QA_PREVIEW")){std::cout<<"PREVIEW READY"<<std::endl;pump(240000);}
 for(int engine=0;engine<(std::getenv("RHYTHMER_QA_UI_ONLY")?0:22);engine++){
  param(*plugin,1)->setValueNotifyingHost(engine/21.f);ready(*plugin);pump(80);double rms=audio(*plugin,head,engine==0?36:60);require(rms>1e-7,"Engine silent "+juce::String(engine));
  if(!std::getenv("RHYTHMER_QA_AUDIO_ONLY"))capture(*editor,out.getChildFile(fmt+"-engine-"+juce::String(engine)+".png"));
 }
 param(*plugin,1)->setValueNotifyingHost(3/21.f);ready(*plugin);param(*plugin,6)->setValueNotifyingHost(.371f);pump(150);audio(*plugin,head);juce::MemoryBlock saved;plugin->getStateInformation(saved);require(saved.getSize()>100,"Missing state");auto value=param(*plugin,6)->getValue();param(*plugin,1)->setValueNotifyingHost(18/21.f);ready(*plugin);plugin->setStateInformation(saved.getData(),int(saved.getSize()));ready(*plugin);require(std::abs(param(*plugin,1)->getValue()-3/21.f)<.0001f,"Engine restore");require(std::abs(param(*plugin,6)->getValue()-value)<.001f,"Sound edit restore");
 if(std::getenv("RHYTHMER_QA_AUDIO_ONLY")){editor->setVisible(false);editor->removeFromDesktop();plugin->editorBeingDeleted(editor.get());editor.reset();plugin->releaseResources();std::cout<<fmt<<" FORMAT_AUDIO_PASS 22 engines, 3 rates, state and custom editor load"<<std::endl;return;}
 for(auto name:{"PLAY","EDIT","KIT"}){param(*plugin,1)->setValueNotifyingHost(0);ready(*plugin);pump(200);click(*editor,name);capture(*editor,out.getChildFile(fmt+"-"+name+".png"));}
 // Exercise the actual full-width on-screen keyboard and input-driven artwork.
 param(*plugin,1)->setValueNotifyingHost(18/21.f);ready(*plugin);click(*editor,"PLAY");capture(*editor,out.getChildFile(fmt+"-layout.png"));auto before=juce::ImageFileFormat::loadFrom(out.getChildFile(fmt+"-layout.png"));int w=before.getWidth(),h=before.getHeight();require(before.getPixelAt(5,h-25).getRed()>240&&before.getPixelAt(w-5,h-25).getRed()>240,"Piano does not fill width");
 mouse(*editor,w*.5f,h-25,NSEventTypeLeftMouseDown);double keyEnergy=0;for(int frame=0;frame<24;frame++){juce::AudioBuffer<float>b(2,512);b.clear();juce::MidiBuffer midi;plugin->processBlock(b,midi);for(int c=0;c<2;c++)for(int n=0;n<512;n++)keyEnergy+=b.getSample(c,n)*b.getSample(c,n);pump(16);if(frame==8)capture(*editor,out.getChildFile(fmt+"-held-a.png"));}capture(*editor,out.getChildFile(fmt+"-held-b.png"));require(keyEnergy>1e-7,"On-screen key did not produce audio");auto held=juce::ImageFileFormat::loadFrom(out.getChildFile(fmt+"-held-b.png"));require(held.getPixelAt(w/2,h-25).getRed()<20,"Held piano key did not invert");auto first=juce::ImageFileFormat::loadFrom(out.getChildFile(fmt+"-held-a.png"));int changed=0,side=std::clamp(int(w*.225),220,290);for(int y=325;y<h-175;y+=4)for(int x=45+side;x<w-45-side;x+=4)changed+=first.getPixelAt(x,y)!=held.getPixelAt(x,y);require(changed>10,"Sustain animation did not evolve");mouse(*editor,w*.5f,h-25,NSEventTypeLeftMouseUp);ready(*plugin);pump(180);capture(*editor,out.getChildFile(fmt+"-released.png"));std::cout<<fmt<<" LAYOUT PASS: four knobs per side, edge-to-edge piano, mouse audio, sustain motion and release changed_pixels="<<changed<<std::endl;
 for(int i=0;i<3;i++){editor->setVisible(false);editor->removeFromDesktop();plugin->editorBeingDeleted(editor.get());editor.reset();editor.reset(plugin->createEditorAndMakeActive());require(editor!=nullptr,"Reopen editor");editor->addToDesktop(juce::ComponentPeer::windowHasTitleBar);editor->setVisible(true);pump(60);}
 editor->setVisible(false);editor->removeFromDesktop();plugin->editorBeingDeleted(editor.get());editor.reset();plugin->releaseResources();std::cout<<fmt<<" FORMAT PASS: audio, 22 engines, state, PLAY/EDIT/KIT, editor reopen"<<std::endl;
}
static VstIntPtr vstHost(AEffect*,int op,int,intptr_t,void*,float){if(op==audioMasterVersion)return 2400;return 0;}
static void vst2(const juce::File& bundle,const juce::File& out){void*h=dlopen(bundle.getChildFile("Contents/MacOS/Rhythmer Engines").getFullPathName().toRawUTF8(),RTLD_NOW|RTLD_LOCAL);if(!h)throw std::runtime_error(dlerror());auto entry=(AEffect*(*)(audioMasterCallback))dlsym(h,"VSTPluginMain");require(entry!=nullptr,"No VST2 entry");auto*e=entry(vstHost);require(e!=nullptr,"No VST2 instance");e->dispatcher(e,effOpen,0,0,nullptr,0);e->dispatcher(e,effSetSampleRate,0,0,nullptr,44100);e->dispatcher(e,effSetBlockSize,0,512,nullptr,0);e->dispatcher(e,effMainsChanged,0,1,nullptr,0);
 NSWindow*w=[[NSWindow alloc]initWithContentRect:NSMakeRect(0,0,1120,820) styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];[w setReleasedWhenClosed:NO];
 for(int i=0;i<3;i++){require(e->dispatcher(e,effEditOpen,0,0,(__bridge void*)[w contentView],0)==1,"VST2 editor open");pump(250);NSView*view=[w contentView];require([[view subviews]count]>0,"No embedded Cocoa view");NSBitmapImageRep*image=[view bitmapImageRepForCachingDisplayInRect:[view bounds]];[view cacheDisplayInRect:[view bounds]toBitmapImageRep:image];NSData*png=[image representationUsingType:NSBitmapImageFileTypePNG properties:@{}];require([png writeToFile:[NSString stringWithUTF8String:out.getChildFile("VST2-editor-"+juce::String(i)+".png").getFullPathName().toRawUTF8()]atomically:YES],"VST2 capture");e->dispatcher(e,effEditClose,0,0,nullptr,0);pump(40);}
 [w close];e->dispatcher(e,effMainsChanged,0,0,nullptr,0);e->dispatcher(e,effClose,0,0,nullptr,0);dlclose(h);std::cout<<"VST2 EDITOR PASS: embedded Cocoa view, three open/close cycles"<<std::endl;
}
int main(int argc,char**argv){juce::ScopedJuceInitialiser_GUI gui;if(!std::getenv("RHYTHMER_QA_AUDIO_ONLY")){[NSApp setActivationPolicy:NSApplicationActivationPolicyRegular];[NSApp activateIgnoringOtherApps:YES];}try{juce::Slider baseline;std::cout<<"HOST SLIDER OK"<<std::endl;require(argc>=3,"Usage: mac-formats artefacts output");juce::File root(argv[1]),out(argv[2]);if(argc==3&&!std::getenv("RHYTHMER_QA_AU_VST3_ONLY"))vst2(root.getChildFile("VST2/Rhythmer Engines.vst"),out);testFormat("VST3",root.getChildFile("VST3/Rhythmer Engines.vst3"),out);testFormat("AudioUnit",root.getChildFile("AU/Rhythmer Engines.component"),out);if(!std::getenv("RHYTHMER_QA_AU_VST3_ONLY"))vst2(root.getChildFile("VST2/Rhythmer Engines.vst"),out);}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}std::cout<<"MAC FORMATS PASS"<<std::endl;return 0;}
